/**
 * Encodes every compiled page of a set to KTX2 (Basis Universal via ktx2-encoder 0.6.0, WASM) and reports sizes.
 *   node ktx2-measure.ts <compiled dir> <out json>
 * Input pixels are premultiplied first (compressed textures cannot be premultiplied at upload like the PNG path),
 * mip chains are generated by the encoder. Two presets:
 *   ETC1S q128 (small download, lower quality) and UASTC level 2 + RDO 1.0 + Zstandard (high quality).
 * GPU bytes after transcoding with alpha: BC7 / ASTC 4x4 / ETC2-EAC = 1 byte per pixel (+ mip chain).
 * Quality is not measured here (no transcoder in this package).
 */
import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { encodeToKTX2 } from './ktx2-pkg/node_modules/ktx2-encoder/dist/node/index.js';
import { decodePng } from 'file:///C:/Project/UVCE_CODEX_CLAUDE/tools/uvce/png.ts';

const [dir, out] = process.argv.slice(2) as [string, string];
const manifest = JSON.parse(await readFile(join(dir, 'manifest.json'), 'utf8')) as { manifestVersion: string; pages: { id: string; file: string; width: number; height: number; mipLevels: number }[] };
const rows: Record<string, unknown>[] = [];
const total = { png: 0, etc1s: 0, uastc: 0, rgba8Mips: 0, compressedGpu: 0 };
for (const p of manifest.pages) {
  const png = await readFile(join(dir, p.file));
  const img = decodePng(png).image;
  const pm = new Uint8Array(img.data.length);
  for (let i = 0; i < img.data.length; i += 4) {
    const a = img.data[i + 3] as number;
    pm[i] = Math.round(((img.data[i] as number) * a) / 255);
    pm[i + 1] = Math.round(((img.data[i + 1] as number) * a) / 255);
    pm[i + 2] = Math.round(((img.data[i + 2] as number) * a) / 255);
    pm[i + 3] = a;
  }
  const decoder = async () => ({ width: img.width, height: img.height, data: pm });
  const common = { isKTX2File: true, generateMipmap: true, isPerceptual: true, isSetKTX2SRGBTransferFunc: true, imageDecoder: decoder } as const;
  const etc1s = await encodeToKTX2(png, { ...common, isUASTC: false, qualityLevel: 128, compressionLevel: 2 });
  const uastc = await encodeToKTX2(png, { ...common, isUASTC: true, uastcLDRQualityLevel: 2, enableRDO: true, rdoQualityLevel: 1, needSupercompression: true });
  let full = 0;
  let w = p.width;
  let h = p.height;
  for (;;) {
    full += w * h;
    if (w === 1 && h === 1) break;
    w = Math.max(1, w >> 1);
    h = Math.max(1, h >> 1);
  }
  const rgba8Mips = full * 4; // encoder builds the full chain; the PNG path clamps at mipLevels (slightly less)
  const compressedGpu = full; // 1 byte per pixel incl. full chain
  total.png += png.byteLength;
  total.etc1s += etc1s.byteLength;
  total.uastc += uastc.byteLength;
  total.rgba8Mips += rgba8Mips;
  total.compressedGpu += compressedGpu;
  rows.push({ page: p.id, size: `${p.width}x${p.height}`, pngBytes: png.byteLength, ktx2Etc1sBytes: etc1s.byteLength, ktx2UastcRdoZstdBytes: uastc.byteLength, gpuRgba8FullChain: rgba8Mips, gpuCompressedFullChain: compressedGpu });
  console.log(`${p.id.padEnd(30)} PNG ${(png.byteLength / 1024).toFixed(0).padStart(5)} KiB  ETC1S ${(etc1s.byteLength / 1024).toFixed(0).padStart(5)} KiB  UASTC+RDO+zstd ${(uastc.byteLength / 1024).toFixed(0).padStart(5)} KiB`);
}
console.log(`TOTAL PNG ${(total.png / 1024).toFixed(0)} KiB, ETC1S ${(total.etc1s / 1024).toFixed(0)} KiB, UASTC ${(total.uastc / 1024).toFixed(0)} KiB; GPU RGBA8 full chain ${(total.rgba8Mips / 1048576).toFixed(2)} MiB -> compressed ${(total.compressedGpu / 1048576).toFixed(2)} MiB`);
await writeFile(out, `${JSON.stringify({ manifestVersion: manifest.manifestVersion, encoder: 'ktx2-encoder 0.6.0 (Basis Universal WASM)', presets: { etc1s: 'ETC1S qualityLevel 128, compressionLevel 2, mips', uastc: 'UASTC level 2 + RDO 1.0 + Zstandard, mips' }, total, rows }, null, 2)}\n`);
